// ===== Second Brain Bot: core (config, HTTP, Telegram, dates, text utils) =====
// Inlined by build.py into every Code node; runs in n8n's task runner and in plain Node for tests.

// __SB_*__ placeholders are filled from config.local.json by build.py --deploy (kept out of git).
const SB = {
  CHAT_ID: '__SB_CHAT_ID__',
  TZ: 'Europe/Paris',
  NOTION_VERSION: '2026-03-11',
  DS: {
    expenses: '__SB_DS_expenses__',
    incomes: '__SB_DS_incomes__',
    transfers: '__SB_DS_transfers__',
    categories: '__SB_DS_categories__',
    accounts: '__SB_DS_accounts__',
    todo: '__SB_DS_todo__',
    notes: '__SB_DS_notes__',
    notecats: '__SB_DS_notecats__',
    goals: '__SB_DS_goals__',
  },
  BRAIN_DUMP_PAGE: '__SB_BRAIN_DUMP_PAGE__',
  SECTIONS: {
    personal: '🤍 Personal', questions: '？Questions', ideas: '💡 Thoughts & Ideas',
    digital: '💻 Digital', recommendations: '⭐ Recommendations', career: '🌱 Career',
  },
  SECTION_MATCH: { personal: /personal/i, questions: /questions/i, ideas: /thoughts/i, digital: /digital/i, recommendations: /recommendations/i, career: /career/i },
  PLACEHOLDERS: ['', 'new task', 'new question', 'new idea', 'new recommendations'],
  TAGS: ['Personel', 'Studies', 'Familly', 'Chores', 'Travel', 'Work', 'Leisure', 'Sport', 'Self-development'],
  INCOME_SOURCES: ['Job', 'Family', 'Scholarship/CAF', 'Freelance', 'Refund'],
  // free tier = 15 requests/min PER MODEL: on 429 the next model takes over
  MODELS: { text: ['gemini-3.5-flash-lite', 'gemini-3.1-flash-lite'], vision: ['gemini-3.8-flash', 'gemini-3.6-flash', 'gemini-3.5-flash-lite', 'gemini-3.1-flash-lite'] },
  // USD per 1M tokens (ai.google.dev/pricing, 2026-11-11). shortcut: fixed USD→EUR rate, update with prices.
  PRICES: { 'gemini-3.5-flash-lite': [0.30, 2.50], 'gemini-3.8-flash': [0.75, 3.75], 'gemini-3.6-flash': [0.75, 3.75], 'gemini-3.1-flash-lite': [0.25, 1.50] },
  USD_EUR: 0.87,
  LIST_TTL_MS: 3600e3,
};

const sleep = ms => new Promise(r => setTimeout(r, ms));
const rid = (n = 10) => Array.from({ length: n }, () => '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'[Math.floor(Math.random() * 62)]).join('');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const eur = n => (Math.round(n * 100) / 100).toFixed(2).replace('.', ',') + ' €';
const clip = (s, n) => (s = String(s ?? '')).length > n ? s.slice(0, n - 1) + '…' : s;

function makeCtx(helpers, env, db, extra = {}) {
  return { helpers, env, db: db || {}, ops: [], logs: [], callbacks: [], now: new Date(), chatId: SB.CHAT_ID, ...extra };
}

function redact(ctx, s) {
  let out = String(s ?? '');
  for (const k of ['SB_NOTION_TOKEN', 'SB_GEMINI_API_KEY', 'SB_TELEGRAM_TOKEN']) if (ctx.env?.[k]) out = out.split(ctx.env[k]).join('***');
  return out.replace(/bot\d+:[A-Za-z0-9_-]{20,}/g, 'bot***');
}

async function http(ctx, o) {
  try {
    return await ctx.helpers.httpRequest({ json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 90000, ...o });
  } catch (e) {
    return { statusCode: 0, body: { message: redact(ctx, e.message) } };
  }
}

// ---------- Notion ----------
async function N(ctx, method, path, body) {
  for (let a = 0; ; a++) {
    const r = await http(ctx, {
      method, url: 'https://api.notion.com/v1' + path, body,
      headers: { Authorization: 'Bearer ' + ctx.env.SB_NOTION_TOKEN, 'Notion-Version': SB.NOTION_VERSION },
    });
    if (r.statusCode >= 200 && r.statusCode < 300) return r.body;
    const retryable = r.statusCode === 0 || r.statusCode === 429 || r.statusCode >= 500;
    if (retryable && a < 2) { await sleep(a ? 3000 : 1000); continue; }
    const err = new Error(`Notion ${method} ${path.split('?')[0]} → ${r.statusCode} ${redact(ctx, r.body?.message || '')}`);
    err.retryable = retryable;
    throw err;
  }
}

async function nQuery(ctx, ds, body = {}, max = 300) {
  const out = [];
  let cursor;
  do {
    const r = await N(ctx, 'POST', `/data_sources/${ds}/query`, { page_size: 100, ...body, ...(cursor ? { start_cursor: cursor } : {}) });
    out.push(...r.results);
    cursor = r.has_more ? r.next_cursor : null;
  } while (cursor && out.length < max);
  return out;
}

const plain = arr => (arr || []).map(t => t.plain_text).join('');
const pTitle = p => plain(Object.values(p.properties || {}).find(x => x.type === 'title')?.title);
const rtext = s => {
  const chunks = [];
  s = String(s ?? '');
  for (let i = 0; i < s.length || i === 0; i += 1900) chunks.push({ type: 'text', text: { content: s.slice(i, i + 1900) } });
  return chunks;
};
const blockUrl = (pageId, blockId) => `https://www.notion.so/${pageId.replace(/-/g, '')}#${blockId.replace(/-/g, '')}`;

// ---------- Telegram ----------
async function T(ctx, method, body) {
  for (let a = 0; ; a++) {
    const r = await http(ctx, { method: 'POST', url: `https://api.telegram.org/bot${ctx.env.SB_TELEGRAM_TOKEN}/${method}`, body });
    if (r.body?.ok) return r.body.result;
    const d = r.body?.description || r.body?.message || String(r.statusCode);
    if (/message is not modified/i.test(d)) return null;
    if ((r.statusCode === 429 || r.statusCode === 0 || r.statusCode >= 500) && a < 2) {
      await sleep(((r.body?.parameters?.retry_after) || 1) * 1000);
      continue;
    }
    throw new Error(`Telegram ${method}: ${redact(ctx, d)}`);
  }
}
const kbMarkup = kb => (kb && kb.length ? { inline_keyboard: kb } : { inline_keyboard: [] });
const tgSend = (ctx, text, kb, extra = {}) => T(ctx, 'sendMessage', {
  chat_id: ctx.chatId, text: clip(text, 4000), parse_mode: 'HTML', link_preview_options: { is_disabled: true }, reply_markup: kbMarkup(kb), ...extra,
  ...(extra.reply_parameters ? { reply_parameters: { allow_sending_without_reply: true, ...extra.reply_parameters } } : {}),
});
const tgEdit = (ctx, message_id, text, kb) => T(ctx, 'editMessageText', {
  chat_id: ctx.chatId, message_id, text: clip(text, 4000), parse_mode: 'HTML', link_preview_options: { is_disabled: true }, reply_markup: kbMarkup(kb),
});
const tgAnswer = (ctx, id, text, alert = false) => T(ctx, 'answerCallbackQuery', { callback_query_id: id, text, show_alert: alert }).catch(() => null);
const tgReact = (ctx, message_id, emoji = '👌') => T(ctx, 'setMessageReaction', { chat_id: ctx.chatId, message_id, reaction: [{ type: 'emoji', emoji }] }).catch(() => null);

async function tgFile(ctx, file_id) {
  const f = await T(ctx, 'getFile', { file_id });
  const r = await ctx.helpers.httpRequest({ url: `https://api.telegram.org/file/bot${ctx.env.SB_TELEGRAM_TOKEN}/${f.file_path}`, encoding: 'arraybuffer', json: false, timeout: 90000 })
    .catch(e => { throw new Error('Telegram file download: ' + redact(ctx, e.message)); });
  return Buffer.from(r).toString('base64');
}

// Button with server-side state: callback_data = 'cb:<token>'.
function btn(ctx, text, action, data = {}, pendingId = null, reusable = false) {
  const token = rid(10);
  ctx.callbacks.push({ token, chat_id: ctx.chatId, action, data, pending_id: pendingId, reusable });
  return { text, callback_data: 'cb:' + token };
}

// ---------- dates (Europe/Paris) ----------
const JOURS = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
function paris(d = new Date()) {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
    timeZone: SB.TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(d).map(x => [x.type, x.value]));
  const date = `${p.year}-${p.month}-${p.day}`;
  return { date, hh: +p.hour, mm: +p.minute, dow: dow(date), time: `${p.hour}:${p.minute}` };
}
const today = ctx => ctx.todayOverride || paris(ctx.now).date;
function addDays(s, n) { const d = new Date(s + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }
function dow(s) { return new Date(s + 'T12:00:00Z').getUTCDay(); }
const daysBetween = (a, b) => Math.round((Date.parse(b + 'T12:00:00Z') - Date.parse(a + 'T12:00:00Z')) / 864e5);
const isDate = s => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !isNaN(Date.parse(s + 'T12:00:00Z'));
const fmtDay = s => isDate(s) ? `${JOURS[dow(s)].slice(0, 3)}. ${s.slice(8, 10)}/${s.slice(5, 7)}` : '?';
function calendar(t, back, fwd) {
  const lines = [];
  for (let i = -back; i <= fwd; i++) {
    const d = addDays(t, i);
    lines.push(`${d} ${JOURS[dow(d)]}${i === 0 ? ' (aujourd\'hui)' : i === 1 ? ' (demain)' : i === -1 ? ' (hier)' : ''}`);
  }
  return lines.join('\n');
}
const weekStart = t => addDays(t, -((dow(t) + 6) % 7)); // Monday
function parisMidnight(s) { // 'YYYY-MM-DD' → ISO timestamp of 00:00 Paris time (CET/CEST aware)
  const off = new Intl.DateTimeFormat('en-US', { timeZone: SB.TZ, timeZoneName: 'shortOffset' }).formatToParts(new Date(s + 'T12:00:00Z')).find(p => p.type === 'timeZoneName').value;
  const m = /GMT([+-])(\d+)(?::(\d+))?/.exec(off) || ['', '+', '0'];
  return `${s}T00:00:00${m[1]}${m[2].padStart(2, '0')}:${(m[3] || '0').padStart(2, '0')}`;
}

// ---------- text similarity (duplicate check, related items) ----------
const norm = s => String(s ?? '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
function trigrams(s) { const t = `  ${norm(s)} `; const set = new Set(); for (let i = 0; i < t.length - 2; i++) set.add(t.slice(i, i + 3)); return set; }
function sim(a, b) {
  const A = trigrams(a), B = trigrams(b);
  let inter = 0; for (const x of A) if (B.has(x)) inter++;
  return inter / (A.size + B.size - inter || 1);
}
function fill(tpl, vars) { return tpl.replace(/\{\{(\w+)\}\}/g, (m, k) => (vars[k] ?? m)); }

// GENERATED by build.py from prompts/*.md — edit the .md files, not this.
const PROMPTS = {
 "braindump": {
  "system": "You file one loose thought from a French student into a section of their Brain Dump page.\n\nSections (output the key):\n- questions: anything phrased or meant as a question to explore later.\n- ideas: an idea, a thought, a project concept, an insight.\n- digital: apps, websites, online accounts, tech setup, tools to try or configure on a computer/phone.\n- recommendations: a book, film, series, podcast, tool or place that SOMEONE recommended or that the user wants to check out.\n- career: internship, job, CV, LinkedIn, school applications, networking.\n- personal: everything else (health, family, wishes, life admin thoughts).\nPriority when several fit: questions > recommendations > career > digital > ideas > personal.\nException: an idea for a project or product is \"ideas\" even if it is technical (\"agent LinkedIn vidéo\" is an idea).\n\n- line: ≤ 15 words, ORIGINAL language, keep the user's wording; drop \"idée:\", \"question:\", \"faut que\".\n- detail: extra context from the input that did not fit in the line, or \"\" (kept for 🔍 Expand).\n\n## Few-shot\n\"idée: agent LinkedIn vidéo\" → {\"section\":\"ideas\",\"line\":\"Agent LinkedIn qui génère des vidéos\",\"detail\":\"\"}\n\"pourquoi les LLM hallucinent plus en français ?\" → {\"section\":\"questions\",\"line\":\"Pourquoi les LLM hallucinent plus en français ?\",\"detail\":\"\"}\n\"Yanis m'a conseillé le livre Deep Work de Cal Newport\" → {\"section\":\"recommendations\",\"line\":\"Deep Work – Cal Newport (conseillé par Yanis)\",\"detail\":\"\"}\n\"tester obsidian pour les cours\" → {\"section\":\"digital\",\"line\":\"Tester Obsidian pour les cours\",\"detail\":\"\"}\n\"demander à mon prof de ML s'il connaît des labos qui prennent des stagiaires en avril\" → {\"section\":\"career\",\"line\":\"Demander au prof de ML des labos pour un stage en avril\",\"detail\":\"\"}\n\"j'aimerais reprendre la natation\" → {\"section\":\"personal\",\"line\":\"Reprendre la natation\",\"detail\":\"\"}",
  "schema": {
   "type": "OBJECT",
   "required": [
    "section",
    "line",
    "detail"
   ],
   "properties": {
    "section": {
     "type": "STRING",
     "enum": [
      "personal",
      "questions",
      "ideas",
      "digital",
      "recommendations",
      "career"
     ]
    },
    "line": {
     "type": "STRING"
    },
    "detail": {
     "type": "STRING"
    }
   }
  }
 },
 "finance": {
  "system": "You turn a French student's message (or a receipt image/PDF) into bookkeeping rows. Today is {{TODAY}} (Europe/Paris).\nThe message was sent on {{MESSAGE_DATE}}.\n\nCalendar for resolving relative dates:\n{{CALENDAR}}\n\nAllowed values (copy spelling exactly):\n- categories: {{CATEGORIES}}\n- accounts: {{ACCOUNTS}}\n- income sources: {{INCOME_SOURCES}}\n\nKinds:\n- expense: the user paid for something.\n- income: money the user received from someone else (salary, family, CAF, refund, sale). A refund is ALWAYS income with income_source \"Refund\".\n- transfer: money moved between TWO OF THE USER'S OWN accounts: ATM withdrawal (bank → Cash Wallet), Revolut top-up (BNP → Revolut), saving (→ Savings Account). NEVER output an expense plus an income for one transfer.\n\nFields:\n- title: short, in the message's language (\"Café\", \"Courses Lidl\", \"Retrait DAB\"). For receipts: merchant + category (\"Lidl – alimentation\").\n- amount: positive number in the receipt/message currency. currency: ISO code. Assume EUR when the user writes \"€\", \"e\", \"euros\" or nothing.\n- date: YYYY-MM-DD. Receipt → the date printed on it. Otherwise resolve relative words (\"hier\", \"samedi dernier\") with the calendar; no date words → {{MESSAGE_DATE}}.\n- category: one allowed category, or \"NEW:<Name>\" ONLY if none fits at all (e.g. \"NEW:Education\" for a course fee). Expenses only.\n  Groceries (\"courses\", supermarket: Lidl, Carrefour, Auchan, Monoprix), bakery, restaurant, café, kebab, fast food → Food & Dining.\n  Clothes, electronics, Amazon orders, household items → Shopping. Rent, phone/internet, electricity, subscriptions billed monthly (Free, SFR) → Bills & Utilities.\n  Streaming, cinema, games, concerts → Entertainment. Bus, train, Uber, fuel, Navigo → Transportation. Pharmacy, doctor, dentist → Healthcare.\n- account / from_account / to_account: an allowed account name, or null when nothing in the input indicates it. Never guess.\n  \"espèces\", \"ESPÈCES\", \"cash\", \"liquide\" → Cash Wallet. \"DAB\"/\"retrait\" → transfer to Cash Wallet (from_account = the bank if named, else null).\n- payment_method: card | cash | transfer | other | null. card_last4: the 4 digits printed on the receipt (\"**** 1234\", \"XXXX1234\"), else null.\n- merchant: shop name or null. items: receipt lines [{name, price}], else [].\n- confidence 0–1 per row; uncertain_fields: names of fields you were not sure about; rationale: one short sentence.\n\nReceipts:\n- Output ONE row per CATEGORY present on the receipt (food lines → Food & Dining row, shampoo → Shopping or Healthcare row), each with its own items and amount = sum of its items.\n- Discounts/remises: subtract from the item they apply to. Deposits (consigne) go with their item.\n- receipt_total: the TOTAL printed on the receipt. If you cannot read a price, set confidence ≤ 0.5 and list \"amount\" in uncertain_fields.\n\n## Few-shot\nMessage date 2026-11-11 (mercredi).\n\"payé 4€ café\" →\n{\"transactions\":[{\"kind\":\"expense\",\"title\":\"Café\",\"amount\":4,\"currency\":\"EUR\",\"date\":\"2026-11-11\",\"merchant\":null,\"items\":[],\"category\":\"Food & Dining\",\"income_source\":null,\"account\":null,\"from_account\":null,\"to_account\":null,\"payment_method\":null,\"card_last4\":null,\"confidence\":0.85,\"uncertain_fields\":[\"account\"],\"rationale\":\"Coffee purchase; no account mentioned.\"}],\"receipt_total\":null}\n\n\"retiré 40 au DAB bnp hier\" →\n{\"transactions\":[{\"kind\":\"transfer\",\"title\":\"Retrait DAB\",\"amount\":40,\"currency\":\"EUR\",\"date\":\"2026-11-10\",\"merchant\":null,\"items\":[],\"category\":null,\"income_source\":null,\"account\":null,\"from_account\":\"BNP\",\"to_account\":\"Cash Wallet\",\"payment_method\":\"other\",\"card_last4\":null,\"confidence\":0.95,\"uncertain_fields\":[],\"rationale\":\"ATM withdrawal moves money from BNP to cash.\"}],\"receipt_total\":null}\n\n\"remboursement amazon 23,99 sur revolut\" →\n{\"transactions\":[{\"kind\":\"income\",\"title\":\"Remboursement Amazon\",\"amount\":23.99,\"currency\":\"EUR\",\"date\":\"2026-11-11\",\"merchant\":\"Amazon\",\"items\":[],\"category\":null,\"income_source\":\"Refund\",\"account\":\"Revolut\",\"from_account\":null,\"to_account\":null,\"payment_method\":\"transfer\",\"card_last4\":null,\"confidence\":0.95,\"uncertain_fields\":[],\"rationale\":\"Refund is income with source Refund.\"}],\"receipt_total\":null}\n\n\"CAF 180 reçu + mis 50 de côté sur l'épargne\" →\ntwo rows: income 180 source \"Scholarship/CAF\" account null; transfer 50 from_account null to_account \"Savings Account\".\n\n\"spent 15 dollars on netflix\" → expense, currency \"USD\", category \"Entertainment\", uncertain_fields [\"currency\"].",
  "schema": {
   "type": "OBJECT",
   "required": [
    "transactions"
   ],
   "properties": {
    "receipt_total": {
     "type": "NUMBER",
     "nullable": true
    },
    "transactions": {
     "type": "ARRAY",
     "items": {
      "type": "OBJECT",
      "required": [
       "kind",
       "title",
       "amount",
       "currency",
       "date",
       "confidence",
       "uncertain_fields",
       "rationale"
      ],
      "properties": {
       "kind": {
        "type": "STRING",
        "enum": [
         "expense",
         "income",
         "transfer"
        ]
       },
       "title": {
        "type": "STRING"
       },
       "amount": {
        "type": "NUMBER"
       },
       "currency": {
        "type": "STRING"
       },
       "date": {
        "type": "STRING",
        "description": "YYYY-MM-DD"
       },
       "merchant": {
        "type": "STRING",
        "nullable": true
       },
       "items": {
        "type": "ARRAY",
        "items": {
         "type": "OBJECT",
         "required": [
          "name",
          "price"
         ],
         "properties": {
          "name": {
           "type": "STRING"
          },
          "price": {
           "type": "NUMBER"
          }
         }
        }
       },
       "category": {
        "type": "STRING",
        "nullable": true
       },
       "income_source": {
        "type": "STRING",
        "nullable": true
       },
       "account": {
        "type": "STRING",
        "nullable": true
       },
       "from_account": {
        "type": "STRING",
        "nullable": true
       },
       "to_account": {
        "type": "STRING",
        "nullable": true
       },
       "payment_method": {
        "type": "STRING",
        "nullable": true,
        "enum": [
         "card",
         "cash",
         "transfer",
         "other"
        ]
       },
       "card_last4": {
        "type": "STRING",
        "nullable": true
       },
       "confidence": {
        "type": "NUMBER"
       },
       "uncertain_fields": {
        "type": "ARRAY",
        "items": {
         "type": "STRING"
        }
       },
       "rationale": {
        "type": "STRING"
       }
      }
     }
    }
   }
  }
 },
 "note": {
  "system": "You turn raw input (typed text, a voice transcript, or a photo of handwritten notes / a whiteboard) into a clean note.\n\n- name: a specific title (≤ 8 words) in the input's language. \"Loi de Poisson – espérance et variance\", not \"Notes de cours\".\n- category: exactly one of {{NOTE_CATEGORIES}}\n  Course/exam content → University. Book/article notes → Reading. Training/sport → Workout. Job/internship/paid project/employer → Work.\n  Association, club, friends, family, recipes, life admin → Personal.\n  Archive is never chosen automatically.\n- cleaned_markdown: the SAME content in the ORIGINAL language: fix spelling and grammar, remove filler (\"euh\", \"du coup\", repetitions),\n  keep every fact, number, formula and name. Use short paragraphs, \"- \" bullets and \"## \" headings only when the input has structure.\n  Do not summarise away details and do not add information. Formulas stay as plain text (e.g. \"E[X] = Var(X) = λ\").\n- raw_text: for a photo, the full text you read, line by line, unchanged (write [illisible] for unreadable parts). For text/voice: \"\" (code keeps the original).\n- suggested_tasks: concrete actions the note asks the user to do (\"exo 3 à refaire\" → \"Refaire l'exercice 3\"), each ≤ 8 words starting with a verb.\n  Empty when there are none. Never turn plain facts into tasks.\n\n## Few-shot\nInput (voice): \"euh donc cours de SED aujourd'hui, en gros un système à événements discrets c'est euh un système dont l'état change à des instants discrets, genre une file d'attente. faut que je relise le chapitre 2 avant le TD\"\nOutput:\n{\"name\":\"SED – définition et exemple\",\"category\":\"University\",\n \"cleaned_markdown\":\"Un système à événements discrets est un système dont l'état change à des instants discrets.\\n\\nExemple : une file d'attente.\",\n \"raw_text\":\"\",\n \"suggested_tasks\":[\"Relire le chapitre 2 avant le TD\"]}\n\nInput (text): \"recette pancakes: 250g farine 2 oeufs 50cl lait 1 sachet levure\"\nOutput: {\"name\":\"Recette pancakes\",\"category\":\"Personal\",\"cleaned_markdown\":\"- 250 g de farine\\n- 2 œufs\\n- 50 cl de lait\\n- 1 sachet de levure\",\"raw_text\":\"\",\"suggested_tasks\":[]}",
  "schema": {
   "type": "OBJECT",
   "required": [
    "name",
    "category",
    "cleaned_markdown",
    "raw_text",
    "suggested_tasks"
   ],
   "properties": {
    "name": {
     "type": "STRING"
    },
    "category": {
     "type": "STRING",
     "enum": [
      "Reading",
      "Archive",
      "Ideas",
      "Workout",
      "Work",
      "University",
      "Personal"
     ]
    },
    "cleaned_markdown": {
     "type": "STRING"
    },
    "raw_text": {
     "type": "STRING"
    },
    "suggested_tasks": {
     "type": "ARRAY",
     "items": {
      "type": "STRING"
     }
    }
   }
  }
