function costEur(model, tin, tout) {
  const p = SB.PRICES[model] || SB.PRICES['gemini-3.5-flash-lite'];
  return +(((tin * p[0] + tout * p[1]) / 1e6) * SB.USD_EUR).toFixed(6);
}

// One structured-output call. Falls back to the next model on overload/quota errors.
async function llm(ctx, { kind, system, parts, schema, models = SB.MODELS.text, think = 'minimal', meta = {} }) {
  let lastErr;
  for (const model of models) {
    for (let a = 0; a < 2; a++) {
      const t0 = Date.now();
      const r = await http(ctx, {
        method: 'POST', url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
        headers: { 'x-goog-api-key': ctx.env.SB_GEMINI_API_KEY }, timeout: 120000,
        body: {
          systemInstruction: { parts: [{ text: system }] },
          contents: [{ role: 'user', parts }],
          generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: schema, thinkingConfig: { thinkingLevel: think } },
        },
      });
      if (r.statusCode === 200) {
        const text = (r.body.candidates?.[0]?.content?.parts || []).filter(p => !p.thought).map(p => p.text || '').join('');
        let out;
        try { out = JSON.parse(text); } catch (e) { lastErr = new Error(`Gemini ${model}: invalid JSON`); continue; }
        const u = r.body.usageMetadata || {};
        const tin = u.promptTokenCount || 0, tout = (u.candidatesTokenCount || 0) + (u.thoughtsTokenCount || 0);
        ctx.logs.push({ extractor_type: kind, model, tokens_in: tin, tokens_out: tout, cost_eur: costEur(model, tin, tout), latency_ms: Date.now() - t0, ...meta });
        return { out, model };
      }
      lastErr = new Error(`Gemini ${model} ${r.statusCode}: ${redact(ctx, r.body?.error?.message || r.body?.message || '')}`);
      if (![0, 429, 500, 502, 503, 504].includes(r.statusCode)) throw lastErr;
      if (r.statusCode === 429) break; // per-model quota: switch model now
      if (a === 0) await sleep(1500);
    }
  }
  throw lastErr;
}

const media = (mime, b64) => ({ inlineData: { mimeType: mime, data: b64 } });

// ---------- live option lists, cached 1 h in brain.cache ----------
async function lists(ctx, fresh = false) {
  const c = ctx.db.cache?.lists;
  if (!fresh && c && Date.now() - Date.parse(c.fetched_at) < SB.LIST_TTL_MS) return c.value;
  const [cats, accts, goals, ncats, inc] = await Promise.all([
    nQuery(ctx, SB.DS.categories), nQuery(ctx, SB.DS.accounts),
    nQuery(ctx, SB.DS.goals, { filter: { property: 'Status', status: { does_not_equal: 'Completed' } } }),
    nQuery(ctx, SB.DS.notecats), N(ctx, 'GET', `/data_sources/${SB.DS.incomes}`),
  ]);
  const num = v => (v?.type === 'number' ? v.number : v?.type === 'rollup' ? (v.rollup?.number ?? 0) : v?.type === 'formula' ? (v.formula?.number ?? 0) : 0) || 0;
  const value = {
    categories: cats.map(p => ({ id: p.id, name: pTitle(p), budget: num(p.properties['Monthly Budget']), spent: num(p.properties['Expense This Month']) })),
    accounts: accts.map(p => ({ id: p.id, name: pTitle(p) })),
    goals: goals.map(p => ({ id: p.id, title: pTitle(p), desc: clip(plain(p.properties.Description?.rich_text), 160), url: p.url })),
    notecats: ncats.map(p => ({ id: p.id, name: pTitle(p) })),
    income_sources: (inc.properties?.Source?.select?.options || []).map(o => o.name),
  };
  ctx.ops.push({ op: 'cache_set', key: 'lists', value });
  ctx.db.cache = { ...(ctx.db.cache || {}), lists: { value, fetched_at: new Date().toISOString() } };
  return value;
}
function invalidateLists(ctx) {
  if (!ctx.invalidated) { ctx.invalidated = true; ctx.ops.push({ op: 'cache_del', key: 'lists' }); }
}

function promptVars(ctx, L, messageDate) {
  const t = today(ctx);
  return {
    TODAY: `${t} (${JOURS[dow(t)]})`,
    MESSAGE_DATE: messageDate || t,
    CALENDAR: calendar(t, 14, 21),
    CATEGORIES: L.categories.map(c => c.name).join(', '),
    ACCOUNTS: L.accounts.map(a => a.name).join(', '),
    INCOME_SOURCES: SB.INCOME_SOURCES.filter(s => L.income_sources.includes(s)).join(', '),
    TAGS: SB.TAGS.join(', '),
    GOALS: L.goals.map((g, i) => `${i}. ${g.title}${g.desc ? ' — ' + g.desc : ''}`).join('\n'),
    NOTE_CATEGORIES: L.notecats.map(c => c.name).join(', '),
  };
}

// ===== Router, extractors, post-processing, validation =====

const PREFIX = { $: 'finance', '!': 'task', '#': 'note', '?': 'braindump' };
const ACCOUNT_ALIASES = [
  [/esp[eè]ces|cash|liquide/i, 'Cash Wallet'],
  [/[ée]pargne|savings|binance/i, 'Savings Account'],
];

async function route(ctx, text, meta = {}) {
  const m = /^\s*([$!#?])\s*/.exec(text);
  if (m) return { prefix: m[1], items: [{ type: PREFIX[m[1]], text_span: text.slice(m[0].length).trim(), confidence: 1 }] };
  const { out } = await llm(ctx, { kind: 'router', system: PROMPTS.router.system, schema: PROMPTS.router.schema, parts: [{ text }], meta });
  const items = (out.items || []).filter(i => i.text_span && i.text_span.trim());
  return { prefix: null, items: items.length ? items : [{ type: 'braindump', text_span: text, confidence: 0.3 }] };
}

const pickName = (list, name) => {
  if (!name) return null;
  const n = norm(name);
  return list.find(x => norm(x.name) === n) || list.find(x => norm(x.name).includes(n) || n.includes(norm(x.name))) || null;
};
function resolveAccount(L, name) {
  if (!name) return null;
  const hit = pickName(L.accounts, name);
  if (hit) return hit;
  for (const [re, target] of ACCOUNT_ALIASES) if (re.test(name)) return pickName(L.accounts, target);
  return null;
}

// ---------- finance ----------
async function extractFinance(ctx, L, { text, file, messageDate, meta }) {
  const parts = [];
  if (file) parts.push(media(file.mime, file.b64));
  parts.push({ text: text || '(receipt attached)' });
  const { out } = await llm(ctx, {
    kind: 'finance', system: fill(PROMPTS.finance.system, promptVars(ctx, L, messageDate)), schema: PROMPTS.finance.schema, parts,
    models: file ? SB.MODELS.vision : SB.MODELS.text, think: file ? 'low' : 'minimal', meta,
  });
  return out;
}

function postFinance(ctx, L, out, src) {
  const txns = out.transactions || [];
  const items = txns.map(t => {
    const d = {
      kind: t.kind, title: clip(t.title || t.merchant || 'Dépense', 80), amount: Math.round((+t.amount || 0) * 100) / 100,
      currency: (t.currency || 'EUR').toUpperCase(), date: isDate(t.date) ? t.date : src.messageDate, merchant: t.merchant || null,
      lines: (t.items || []).map(x => ({ name: x.name, price: +x.price || 0 })), rationale: t.rationale || '',
      category: null, category_new: null, income_source: null, account: null, from_account: null, to_account: null,
      card_last4: /^\d{4}$/.test(t.card_last4 || '') ? t.card_last4 : null, payment_method: t.payment_method || null,
    };
    const uncertain = new Set(t.uncertain_fields || []);
    if (d.kind === 'expense') {
      const nw = /^NEW:\s*(.+)$/i.exec(t.category || '');
      const c = nw ? pickName(L.categories, nw[1]) : pickName(L.categories, t.category);
      if (c) d.category = { id: c.id, name: c.name };
      else if (nw) d.category_new = clip(nw[1].trim(), 40);
      else uncertain.add('category');
    }
    if (d.kind === 'income') d.income_source = L.income_sources.includes(t.income_source) ? t.income_source : (/refund|rembours/i.test(t.title) ? 'Refund' : null);
    const acc = n => { const a = resolveAccount(L, n); return a ? { id: a.id, name: a.name } : null; };
    if (d.kind === 'transfer') { d.from_account = acc(t.from_account); d.to_account = acc(t.to_account); }
    else {
      d.account = acc(t.account) || (d.payment_method === 'cash' ? acc('Cash Wallet') : null);
      if (!d.account && d.card_last4) {
        const m = (ctx.db.card_map || []).find(c => c.card_last4 === d.card_last4);
        if (m && L.accounts.some(a => a.id === m.account_page_id)) d.account = { id: m.account_page_id, name: m.account };
      }
    }
    return { type: 'finance', data: d, confidence: Math.max(0, Math.min(1, +t.confidence || 0.5)), uncertain: [...uncertain], warnings: [] };
  });
  if (out.receipt_total != null && items.length) {
    const sum = items.reduce((s, i) => s + i.data.amount, 0);
    if (Math.abs(sum - out.receipt_total) > 0.05) {
      for (const i of items) { i.confidence = Math.min(i.confidence, 0.5); i.uncertain = [...new Set([...i.uncertain, 'amount'])]; }
      items[0].warnings.push(`Total des lignes ${eur(sum)} ≠ total du ticket ${eur(out.receipt_total)}`);
    }
  }
  return items;
}

// Blocking errors (no ✅ button until fixed) and warnings, per finance line.
function validateFinance(ctx, it) {
  const d = it.data, t = today(ctx), errors = [], warnings = [];
  if (!(d.amount > 0)) errors.push('montant invalide');
  if (!isDate(d.date)) errors.push('date invalide');
  else {
    if (daysBetween(t, d.date) > 1) errors.push('date dans le futur');
    if (daysBetween(d.date, t) > 365) errors.push('date de plus d\'un an');
  }
  if (d.currency !== 'EUR') warnings.push(`devise ${d.currency} : montant non converti`);
  if (d.kind === 'expense' && !d.category && !d.category_new) errors.push('catégorie manquante');
  if (d.kind === 'transfer' && d.from_account && d.to_account && d.from_account.id === d.to_account.id) errors.push('virement vers le même compte');
  return { errors, warnings };
}
const needsAccount = d => (d.kind === 'transfer' ? (!d.from_account ? 'from_account' : !d.to_account ? 'to_account' : null) : (!d.account ? 'account' : null));

// ---------- task ----------
async function extractTask(ctx, L, { text, meta }) {
  const { out } = await llm(ctx, { kind: 'task', system: fill(PROMPTS.task.system, promptVars(ctx, L)), schema: PROMPTS.task.schema, parts: [{ text }], meta });
  return out;
}
function priorityFor(t, due, urgent) {
  const d = due ? daysBetween(t, due) : null;
  if (urgent || (d !== null && d <= 2)) return 'High';
  if (d !== null && d <= 7) return 'Medium';
  return 'Low';
}
function postTask(ctx, L, out) {
  const t = today(ctx), warnings = [];
  let due = isDate(out.due_date) ? out.due_date : null;
  if (due && due < t && !out.due_is_past_ok) { warnings.push(`date passée (${fmtDay(due)}) ignorée`); due = null; }
  const g = Number.isInteger(out.goal_index) ? L.goals[out.goal_index] : null;
  const conf = +out.goal_confidence || 0;
  const d = {
    name: clip(out.name || 'Tâche', 100), due_date: due, urgent: !!out.urgent,
    priority: priorityFor(t, due, out.urgent), priority_reason: out.priority_reason || '',
    tags: [...new Set((out.tags || []).filter(x => SB.TAGS.includes(x)))].slice(0, 2),
    goal: g && conf >= 0.7 ? { id: g.id, title: g.title } : null,
    goal_suggestion: g && conf < 0.7 && conf >= 0.3 ? { id: g.id, title: g.title } : null,
  };
  return { type: 'task', data: d, confidence: 0.9, warnings, uncertain: [] };
}

// ---------- note ----------
async function extractNote(ctx, L, { text, file, meta }) {
  const schema = JSON.parse(JSON.stringify(PROMPTS.note.schema));
  schema.properties.category.enum = L.notecats.map(c => c.name);
  const parts = [];
  if (file) parts.push(media(file.mime, file.b64));
  parts.push({ text: text || '(photo of notes attached)' });
  const { out } = await llm(ctx, {
    kind: 'note', system: fill(PROMPTS.note.system, promptVars(ctx, L)), schema, parts,
    models: file ? SB.MODELS.vision : SB.MODELS.text, think: file ? 'low' : 'minimal', meta,
  });
  return out;
}
function postNote(ctx, L, out, src) {
  const c = pickName(L.notecats, out.category) || pickName(L.notecats, 'Personal');
  return {
    type: 'note', confidence: 0.9, warnings: [], uncertain: [],
    data: {
      name: clip(out.name || 'Note', 100), category: c ? { id: c.id, name: c.name } : null,
      body: out.cleaned_markdown || src.text, raw: src.file ? (out.raw_text || '') : (src.raw || src.text),
      suggested_tasks: (out.suggested_tasks || []).slice(0, 5), tasks_created: false,
    },
  };
}

// ---------- brain dump ----------
async function extractBraindump(ctx, L, { text, meta }) {
  const { out } = await llm(ctx, { kind: 'braindump', system: PROMPTS.braindump.system, schema: PROMPTS.braindump.schema, parts: [{ text }], meta });
  return out;
}
function postBraindump(ctx, out, src) {
  const words = String(out.line || src.text).trim().split(/\s+/);
  return {
    type: 'braindump', confidence: 0.9, warnings: [], uncertain: [],
    data: { section: SB.SECTIONS[out.section] ? out.section : 'personal', line: words.slice(0, 15).join(' '), detail: out.detail || '', expanded: null },
  };
}

// Runs the right extractor for one routed span; returns 1..n batch items.
async function extractItem(ctx, L, type, span, src, meta) {
  if (type === 'finance') return postFinance(ctx, L, await extractFinance(ctx, L, { text: span, file: src.file, messageDate: src.messageDate, meta }), src);
  if (type === 'task') return [postTask(ctx, L, await extractTask(ctx, L, { text: span, meta }))];
  if (type === 'note') return [postNote(ctx, L, await extractNote(ctx, L, { text: span, file: src.file, meta }), { ...src, text: span })];
  return [postBraindump(ctx, await extractBraindump(ctx, L, { text: span, meta }), { text: span })];
}

// ---------- duplicate check (warnings only; never blocks) ----------
async function dupWarning(ctx, it) {
  try {
    const d = it.data;
    if (it.type === 'finance') {
      const ds = { expense: SB.DS.expenses, income: SB.DS.incomes, transfer: SB.DS.transfers }[d.kind];
      if (!isDate(d.date)) return null;
      const rows = await nQuery(ctx, ds, { filter: { and: [
        { property: 'Date', date: { on_or_after: addDays(d.date, -3) } }, { property: 'Date', date: { on_or_before: addDays(d.date, 3) } },
        { property: 'Amount', number: { equals: d.amount } }] } }, 50);
      const hit = rows.find(p => sim(pTitle(p), d.title) >= 0.5 || p.properties.Date?.date?.start === d.date);
      return hit ? `doublon possible : « ${pTitle(hit)} » ${eur(d.amount)} le ${fmtDay(hit.properties.Date?.date?.start)}` : null;
    }
    if (it.type === 'task') {
      const rows = await nQuery(ctx, SB.DS.todo, { filter: { property: 'Status', status: { does_not_equal: 'Done' } }, sorts: [{ timestamp: 'created_time', direction: 'descending' }] }, 200);
      const hit = rows.find(p => sim(pTitle(p), d.name) >= 0.6);
      return hit ? `tâche similaire déjà ouverte : « ${pTitle(hit)} »` : null;
    }
    if (it.type === 'note') {
      const rows = await nQuery(ctx, SB.DS.notes, { filter: { timestamp: 'created_time', created_time: { on_or_after: addDays(today(ctx), -60) } } }, 200);
      const hit = rows.find(p => sim(pTitle(p), d.name) >= 0.6);
      return hit ? `note similaire : « ${pTitle(hit)} »` : null;
    }
    if (it.type === 'braindump') {
      const hit = (await bdItems(ctx, d.section)).find(b => sim(b.text, d.line) >= 0.6);
      return hit ? `déjà dans ${SB.SECTIONS[d.section]} : « ${clip(hit.text, 60)} »` : null;
    }
  } catch (e) { return null; }
  return null;
}

// ===== Notion writes: pages, Brain Dump blocks, undo, budgets =====

const para = (text, color) => ({ object: 'block', type: 'paragraph', paragraph: { rich_text: rtext(text), ...(color ? { color } : {}) } });
const bullet = text => ({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: rtext(text) } });
const linkPara = (label, links) => ({
  object: 'block', type: 'paragraph', paragraph: {
    rich_text: [{ type: 'text', text: { content: label } }, ...links.flatMap((l, i) => [
      ...(i ? [{ type: 'text', text: { content: ' · ' } }] : []), { type: 'text', text: { content: clip(l.title, 80), link: { url: l.url } } }])],
  },
});
function mdBlocks(md) {
  const out = [];
  for (const raw of String(md || '').split(/\n+/)) {
    const line = raw.trim();
    if (!line) continue;
    if (/^#{1,3}\s/.test(line)) out.push({ object: 'block', type: 'heading_3', heading_3: { rich_text: rtext(line.replace(/^#+\s*/, '')) } });
    else if (/^[-*•]\s/.test(line)) out.push(bullet(line.replace(/^[-*•]\s*/, '')));
    else out.push(para(line));
  }
  return out.slice(0, 90);
}
const sourceLine = src => `Source : ${src.input_type || 'texte'} · ${src.message_date || ''} ${src.message_time || ''} · Second Brain Bot`;

const rel = x => ({ relation: x ? [{ id: x.id }] : [] });
const titleProp = s => ({ title: rtext(s) });

function financeProps(d) {
  const base = { Amount: { number: d.amount }, Date: { date: { start: d.date } } };
  if (d.kind === 'expense') return { ...base, Expense: titleProp(d.title), Category: rel(d.category), Account: rel(d.account) };
  if (d.kind === 'income') return { ...base, Income: titleProp(d.title), Source: { select: d.income_source ? { name: d.income_source } : null }, Accounts: rel(d.account) };
  return { ...base, Transactions: titleProp(d.title), 'From Account': rel(d.from_account), 'To Account': rel(d.to_account) };
}
const financeDS = d => ({ expense: SB.DS.expenses, income: SB.DS.incomes, transfer: SB.DS.transfers }[d.kind]);
function taskProps(d) {
  return {
    Name: titleProp(d.name), Priority: { select: { name: d.priority } },
    'Due date': { date: d.due_date ? { start: d.due_date } : null },
    'Multi-select': { multi_select: d.tags.map(name => ({ name })) }, Goal: rel(d.goal),
  };
}
const noteProps = d => ({ Name: titleProp(d.name), Category: rel(d.category) });

async function createPage(ctx, ds, properties, children) {
  const p = await N(ctx, 'POST', '/pages', { parent: { type: 'data_source_id', data_source_id: ds }, properties, ...(children?.length ? { children } : {}) });
  invalidateLists(ctx);
  return { id: p.id, url: p.url, kind: 'page' };
}

async function ensureCategory(ctx, L, d) {
  if (d.category || !d.category_new) return;
  const existing = pickName(L.categories, d.category_new);
  if (existing) { d.category = { id: existing.id, name: existing.name }; d.category_new = null; return; }
  const p = await createPage(ctx, SB.DS.categories, { Category: titleProp(d.category_new) });
  L.categories.push({ id: p.id, name: d.category_new, budget: 0, spent: 0 });
  d.category = { id: p.id, name: d.category_new };
  d.category_new = null;
}

async function saveItem(ctx, L, batch, it) {
  const d = it.data, src = batch.payload.source;
  if (it.type === 'finance') {
    await ensureCategory(ctx, L, d);
    const body = [];
    if (d.lines.length) body.push(para('Articles'), ...d.lines.slice(0, 60).map(l => bullet(`${l.name} — ${eur(l.price)}`)));
    if (d.merchant) body.push(para('Commerçant : ' + d.merchant));
    if (d.card_last4) body.push(para('Carte •••• ' + d.card_last4));
    body.push(para(sourceLine(src), 'gray'));
    it.notion = await createPage(ctx, financeDS(d), financeProps(d), body);
  } else if (it.type === 'task') {
    it.notion = await createPage(ctx, SB.DS.todo, { ...taskProps(d), Status: { status: { name: 'Not started' } } }, [
      para(`Priorité ${d.priority} : ${d.priority_reason}`), para(sourceLine(src), 'gray')]);
  } else if (it.type === 'note') {
    const body = mdBlocks(d.body);
    if (d.raw) body.push({ object: 'block', type: 'toggle', toggle: { rich_text: rtext(`Texte brut (${src.input_type || 'texte'})`), children: String(d.raw).match(/[\s\S]{1,1900}/g).slice(0, 50).map(c => para(c)) } });
    body.push(para(sourceLine(src), 'gray'));
    it.notion = await createPage(ctx, SB.DS.notes, noteProps(d), body);
  } else if (it.type === 'braindump') {
    it.notion = await bdInsert(ctx, d.section, d.line);
  }
  it.state = 'saved';
  it.saved_at = new Date().toISOString();
}

async function updateItem(ctx, L, batch, it, fields) {
  const d = it.data;
  if (it.type === 'finance') {
    await ensureCategory(ctx, L, d);
    if (fields.includes('kind')) { await trashItem(ctx, it); return saveItem(ctx, L, batch, it); }
    return N(ctx, 'PATCH', `/pages/${it.notion.id}`, { properties: financeProps(d) });
  }
  if (it.type === 'task') return N(ctx, 'PATCH', `/pages/${it.notion.id}`, { properties: taskProps(d) });
  if (it.type === 'note') return N(ctx, 'PATCH', `/pages/${it.notion.id}`, { properties: noteProps(d) });
  if (it.type === 'braindump') {
    if (fields.includes('section')) { await trashItem(ctx, it); it.notion = await bdInsert(ctx, d.section, d.line); return; }
    return N(ctx, 'PATCH', `/blocks/${it.notion.id}`, { to_do: { rich_text: rtext(d.line) } });
  }
}

async function trashItem(ctx, it) {
  if (!it.notion) return;
  try {
    if (it.notion.kind === 'block') await N(ctx, 'DELETE', `/blocks/${it.notion.id}`);
    else await N(ctx, 'PATCH', `/pages/${it.notion.id}`, { in_trash: true });
  } catch (e) { if (!/→ (404|400)/.test(e.message)) throw e; } // already gone
}

// ---------- Brain Dump page ----------
async function bdColumns(ctx) {
  if (ctx.db.config?.braindump) return ctx.db.config.braindump;
  const cols = {};
  const top = (await N(ctx, 'GET', `/blocks/${SB.BRAIN_DUMP_PAGE}/children?page_size=100`)).results.filter(b => b.type === 'column_list');
  for (const cl of top) {
    for (const col of (await N(ctx, 'GET', `/blocks/${cl.id}/children?page_size=100`)).results) {
      const kids = (await N(ctx, 'GET', `/blocks/${col.id}/children?page_size=100`)).results;
      const h = kids.find(b => b.type.startsWith('heading_'));
      const key = h && Object.keys(SB.SECTION_MATCH).find(k => SB.SECTION_MATCH[k].test(plain(h[h.type].rich_text)));
      if (key) cols[key] = { column_id: col.id, heading_id: h.id };
    }
  }
  if (Object.keys(cols).length !== 6) throw new Error(`Brain Dump: found ${Object.keys(cols).length}/6 sections`);
  ctx.ops.push({ op: 'config_set', key: 'braindump', value: cols });
  ctx.db.config = { ...(ctx.db.config || {}), braindump: cols };
  return cols;
}
async function bdChildren(ctx, key) {
  const col = (await bdColumns(ctx))[key];
  const out = [];
  let cursor;
  do {
    const r = await N(ctx, 'GET', `/blocks/${col.column_id}/children?page_size=100${cursor ? '&start_cursor=' + cursor : ''}`);
    out.push(...r.results); cursor = r.has_more ? r.next_cursor : null;
  } while (cursor);
  return { col, kids: out };
}
const isPlaceholder = b => SB.PLACEHOLDERS.includes(norm(plain(b.to_do?.rich_text)));
async function bdItems(ctx, key) {
  const { kids } = await bdChildren(ctx, key);
  return kids.filter(b => b.type === 'to_do' && !isPlaceholder(b))
    .map(b => ({ id: b.id, text: plain(b.to_do.rich_text), created: b.created_time, checked: b.to_do.checked, section: key, url: blockUrl(SB.BRAIN_DUMP_PAGE, b.id) }));
}
// New to_do goes right after the section's last to_do (before the divider), via the 2026-03-11 `position` param.
async function bdInsert(ctx, key, line) {
  const { col, kids } = await bdChildren(ctx, key);
  const todos = kids.filter(b => b.type === 'to_do');
  const after = todos.length ? todos[todos.length - 1].id : col.heading_id;
  const r = await N(ctx, 'PATCH', `/blocks/${col.column_id}/children`, {
    children: [{ object: 'block', type: 'to_do', to_do: { rich_text: rtext(line), checked: false } }],
    position: { type: 'after_block', after_block: { id: after } },
  });
  const b = r.results[0];
  return { id: b.id, url: blockUrl(SB.BRAIN_DUMP_PAGE, b.id), kind: 'block' };
}

// ---------- budgets ----------
async function budgetLines(ctx, categoryIds) {
  const lines = [];
  for (const id of [...new Set(categoryIds)]) {
    const p = await N(ctx, 'GET', `/pages/${id}`);
    const name = pTitle(p);
    const budget = p.properties['Monthly Budget']?.number || 0;
    const r = p.properties['Expense This Month']?.rollup;
    const spent = r?.number ?? 0;
    if (!budget) { lines.push(`${esc(name)} : ${eur(spent)} ce mois (pas de budget)`); continue; }
    const pct = Math.round((spent / budget) * 100);
    lines.push(`${pct >= 100 ? '🚨 ' : pct >= 80 ? '⚠️ ' : ''}${esc(name)} : ${eur(spent).replace(' €', '')}/${eur(budget)} (${pct}%)`);
  }
  return lines;
}

// ===== Batch recap message + keyboard (one message per batch, edited in place) =====

const KIND_EMOJI = { expense: '🔴', income: '🟢', transfer: '🔁' };
const live = it => !['deleted', 'cancelled', 'undone'].includes(it.state);
const pendingFinance = b => b.payload.items.filter(i => i.type === 'finance' && i.state === 'pending');

function fieldTxt(it, field, text) {
  return it.uncertain?.includes(field) ? `<b>${text}?</b>` : text;
}

function itemLines(it) {
  const n = it.idx + 1, d = it.data, out = [];
  const done = it.state === 'saved' && it.notion ? ` → <a href="${esc(it.notion.url)}">Notion</a>` : '';
  const strike = s => (live(it) ? s : `<s>${s}</s>`);
  if (it.state === 'needs_type') {
    out.push(`${n}. ❓ « ${esc(clip(it.span, 80))} » — c'est quoi ?`);
    return out;
  }
  if (it.type === 'finance') {
    const where = d.kind === 'transfer'
      ? `${d.from_account ? esc(d.from_account.name) : '<b>compte source ?</b>'} → ${d.to_account ? esc(d.to_account.name) : '<b>compte cible ?</b>'}`
      : (d.account ? fieldTxt(it, 'account', esc(d.account.name)) : `<b>compte ?</b>${d.card_last4 ? ` (carte ••${d.card_last4})` : ''}`);
    const cat = d.kind === 'expense' ? (d.category ? fieldTxt(it, 'category', esc(d.category.name)) : d.category_new ? `🆕 <b>${esc(d.category_new)}</b> (nouvelle catégorie)` : '<b>catégorie ?</b>')
      : d.kind === 'income' ? (d.income_source ? esc(d.income_source) : '<b>source ?</b>') : 'virement';
    const ok = it.confidence >= 0.8 && !it.uncertain?.length ? '✓' : '⚠️';
    out.push(strike(`${n}. ${KIND_EMOJI[d.kind]} ${esc(d.title)} — ${fieldTxt(it, 'amount', eur(d.amount))}${d.currency !== 'EUR' ? ' ' + esc(d.currency) : ''} · ${cat} · ${where} · ${fieldTxt(it, 'date', fmtDay(d.date))} ${ok}`) + done);
    for (const l of d.lines.slice(0, 8)) out.push(`    • ${esc(clip(l.name, 40))} ${eur(l.price)}`);
    if (d.lines.length > 8) out.push(`    • … +${d.lines.length - 8} articles`);
  } else if (it.type === 'task') {
    const goal = d.goal ? ` · 🎯 ${esc(clip(d.goal.title, 40))}` : '';
    out.push(strike(`${n}. ✅ Tâche <b>${esc(d.name)}</b> · ${d.due_date ? fmtDay(d.due_date) : 'sans date'} · ${d.priority} · ${esc(d.tags.join(', ') || '—')}${goal}`) + done);
    if (d.priority_reason && live(it)) out.push(`    <i>${esc(d.priority_reason)}</i>`);
  } else if (it.type === 'note') {
    out.push(strike(`${n}. 📝 Note <b>${esc(d.name)}</b> · ${esc(d.category?.name || '?')}`) + done);
    if (d.suggested_tasks.length && !d.tasks_created && live(it)) for (const t of d.suggested_tasks) out.push(`    ☐ ${esc(t)}`);
  } else if (it.type === 'braindump') {
    out.push(strike(`${n}. 💭 ${SB.SECTIONS[d.section]} : « ${esc(d.line)} »`) + done);
    if (d.expanded) out.push(`    🔍 ${esc(d.expanded)}`);
  }
  if (it.state === 'failed') out.push('    ⏳ Notion indisponible, nouvel essai automatique');
  if (it.state === 'undone') out.push('    ↩️ annulé (corbeille Notion)');
  for (const e of it.errors || []) if (live(it)) out.push(`    ❌ ${esc(e)}`);
  for (const w of it.warnings || []) if (live(it)) out.push(`    ⚠️ ${esc(w)}`);
  return out;
}

function renderBatch(ctx, b, L) {
  const p = b.payload, items = p.items, pid = b.id;
  const fin = pendingFinance(b);
  const lines = [];
  if (b.status === 'open' && fin.length) lines.push('🧾 <b>À confirmer</b> — rien n\'est enregistré avant ✅');
  else if (b.status === 'cancelled') lines.push('❌ <b>Annulé</b>');
  else if (b.status === 'expired') lines.push('⌛ <b>Expiré</b> (annulé après 48 h)');
  else if (b.status === 'undone') lines.push('↩️ <b>Annulé</b> — pages mises à la corbeille');
  else if (b.status === 'retrying') lines.push('⏳ <b>Enregistrement partiel</b> — Notion ne répond pas, je réessaie');
  else lines.push('✅ <b>Enregistré</b>');
  if (p.source?.transcript) lines.push(`🎙 <i>${esc(clip(p.source.transcript, 300))}</i>`);
  for (const it of items) lines.push(...itemLines(it));
  if (p.budget_lines?.length) lines.push('', '📊 <b>Budgets</b>', ...p.budget_lines);
  if (p.note) lines.push('', p.note);

  const kb = [];
  if (['cancelled', 'expired', 'undone'].includes(b.status)) return { text: lines.join('\n'), kb };

  const nt = items.find(i => i.state === 'needs_type');
  if (nt) kb.push([['💸 Finance', 'finance'], ['✅ Tâche', 'task'], ['📝 Note', 'note'], ['💭 Idée', 'braindump']].map(([t, v]) => btn(ctx, t, 'type', { idx: nt.idx, type: v }, pid)));
  if (p.photo_ask) kb.push([['🧾 Reçu', 'receipt'], ['📝 Note', 'note'], ['🚫 Ignorer', 'ignore']].map(([t, v]) => btn(ctx, t, 'photo', { kind: v }, pid)));

  if (b.status === 'open' && fin.length) {
    const missing = fin.find(i => needsAccount(i.data));
    if (missing && L) {
      const field = needsAccount(missing.data);
      const label = { account: 'Compte', from_account: 'Depuis', to_account: 'Vers' }[field];
      kb.push([{ text: `${label} pour la ligne ${missing.idx + 1} ⤵`, callback_data: 'noop' }]);
      const accBtns = L.accounts.map(a => btn(ctx, a.name, 'acct', { idx: missing.idx, field, id: a.id, name: a.name, card: missing.data.card_last4 }, pid));
      for (let i = 0; i < accBtns.length; i += 3) kb.push(accBtns.slice(i, i + 3));
    }
    const blocked = fin.some(i => i.errors?.length || needsAccount(i.data));
    kb.push([
      ...(blocked ? [] : [btn(ctx, '✅ Tout enregistrer', 'save', {}, pid)]),
      btn(ctx, '✏️ Modifier', 'edit', {}, pid, true), btn(ctx, '❌ Annuler', 'cancel', {}, pid)]);
    if (fin.length > 1) kb.push(fin.map(i => btn(ctx, `🗑 ${i.idx + 1}`, 'del', { idx: i.idx }, pid)));
  }
  const saved = items.filter(i => i.state === 'saved');
  for (const it of saved) {
    if (it.type === 'task' && it.data.goal_suggestion && !it.data.goal) kb.push([btn(ctx, `🎯 ${it.idx + 1} → ${clip(it.data.goal_suggestion.title, 40)}`, 'goal', { idx: it.idx }, pid)]);
    if (it.type === 'note' && it.data.suggested_tasks.length && !it.data.tasks_created) kb.push([btn(ctx, `➕ Créer ${it.data.suggested_tasks.length} tâche${it.data.suggested_tasks.length > 1 ? 's' : ''}`, 'mktasks', { idx: it.idx }, pid)]);
    if (it.type === 'braindump' && !it.data.expanded) kb.push([btn(ctx, `🔍 Développer ${it.idx + 1}`, 'expand', { idx: it.idx }, pid)]);
  }
  if (saved.length || items.some(i => i.state === 'failed')) {
    const row = [];
    if (!(b.status === 'open' && fin.length)) row.push(btn(ctx, '✏️ Modifier', 'edit', {}, pid, true));
    if (saved.length) row.push(btn(ctx, '↩️ Annuler', 'undo', {}, pid));
    kb.push(row);
  }
  return { text: lines.join('\n'), kb };
}

